@torch.no_grad()
def evaluate(student, batches):
    student.eval()
    correct, count = 0, 0
    for features, labels in batches:
        predictions = student(features).argmax(dim=-1)
        correct += (predictions == labels).sum().item()
        count += len(labels)
    return correct / count if count else None
